__NUXT_JSONP__("/it", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002F52.198.144.187:81",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"3 Ragioni per scegliere MLI",subtitle:"(Mentor Language Institute)",lists:[{image:"\u002Fimages\u002Fhome\u002Fit\u002Fpeople-choose-mli-1.jpg",title:"Hollywood e Westwood",description:"MLI si trova in un'eccellente e famosa area di Los Angeles. Gli studenti hanno l'opportunità di studiare l'inglese e allo stesso tempo godersi Los Angeles.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fit\u002Fpeople-choose-mli-2.jpg",title:"Corsi di mattina, pomeriggio e sera",description:"Offriamo corsi di mattina, pomeriggio e sera ideati per persone che necessitano di maggiore flessibilità.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fit\u002Fpeople-choose-mli-3.jpg",title:"$201 a settimana",description:"Ottima Location e Prezzi ragionevoli! Ti invitiamo a confrontare i nostri prezzi con quelli delle altre scuole di Inglese! Per informazioni sui prezzi, cliccare su Contattaci.",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fit\u002Fmli-highly-rated.jpg",courses:{title:"Corsi",lists:[{image:d,title:"Programma ESL",subtitle:["Questo programma è composto da tre sezioni: Comprensione orale\u002FConversazione, Comprensione scritta\u002FLessico, e Grammatica\u002FProduzione scritta. Questo programma è ideale per gli studenti che intendono migliorare le loro generali capacità comunicative in lingua inglese."]},{image:e,title:"TOEFL®",subtitle:["Il programma TOEFL offerto da MLI consiste in un corso intensivo volto all'acquisizione delle abilità e strategie necessarie ad ottenere un ottimo punteggio nelle quattro sezioni dell'iBT (Internet-Based Test)."]},{image:d,title:"Programma Vacation ESL (per uno studente di breve durata)",subtitle:["Questo programma è composto da lezioni di ascolto\u002Fconversazione, lettura\u002Fvocabolario e grammatica\u002Fscrittura. \u003Cbr\u003EOffriamo il programma Vacation ESL per gli studenti che vogliono studiare l'inglese per un breve periodo."]},{image:e,title:"IELTS™",subtitle:["IELTS è un test, sviluppato in Inghilterra e Australia, per la certificazione dell'abilità dello studente nella lingua inglese. Di recente, molte università americane richiedono il punteggio TOEFL ovvero quello IELTS.  Il programma si compone di quattro sezioni: comprensione orale, comunicazione, lettura e Produzione scritta. Questo corso è volto all'acquisizione delle capacità\u002Fstrategie per il conseguimento di un alto punteggio in ciascuna sezione. "]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Programma di conversazione",subtitle:["Il nostro programma si concentra sul potenziamento delle tue competenze conversazionali in inglese attraverso attività coinvolgenti e apprendimento interattivo! Nelle nostre lezioni di conversazione, gli studenti esploreranno un'ampia gamma di vocabolario, frasi ed espressioni idiomatiche che renderanno le tue conversazioni vivaci. Esercita la tua pronuncia nella nostra classe CMAR. Attraverso discussioni divertenti, giochi di ruolo e attività di gruppo, acquisirai fiducia nell'esprimerti e nel partecipare a conversazioni significative. I nostri istruttori esperti offrono un ambiente di apprendimento di supporto, guidandoti in un viaggio alla scoperta della lingua."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"Programma Business plus TOEIC®",subtitle:["Il test TOEIC® e' finalizzato a testare la conoscenza di inglese commerciale e viene utilizzato da molte societa' e organizzazioni in tutto il mondo. In aggiunta al regolare programma business, il programma di preparazione all'esame TOEIC® ha l'obiettivo di preparare gli studenti al superamento del TOEIC®- ascolto e lettura introducendo il vocabolario essenziale ed esplorando le strategie per ottenere un punteggio alto nel test.","Questo programma e' utile per migliorare le proprie abilita' nella lingua inglese come il vocabolario, la lettura, l'ascolto e la grammatica. Attraverso l'apprendimento delle strategie per individuare le risposte corrette lo studente sara' in grado di raggiungere un punteggio alto."]}]},schedule:"\u002Fimages\u002Fhome\u002Fit\u002Ffree_trial_banner_it.png",link:"\u002Fit\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"Location \u002F Campus",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Westwood Campus",subtitle:"Westwood è un'area vivace ed unica nel suo genere, situata nella parte occidentale di Los Angeles. Westwood è particolarmente conosciuta per essere la sede di UCLA, una delle più prestigiose Università della California. È un quartiere entusiasmante e ricco di divertimento per gli studenti grazie alla presenza di moltissimi negozi,ristoranti e posti tranquilli in cui trascorrere la serata. Il nostro campus si trova di fronte al museo d'arte  e centro culturale di rilevanza internazionale \"Hammer Museum\".",read_more:["\u003Ca href=\"\u002Fit\u002Fwestwood\u002F\"\u003E» Per maggiori informazioni\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Hollywood Campus",subtitle:"Il campus situato in Hollywood si trova accanto al famoso Chinese Theater. Il quartiere di Hollywood presenta famosi cinema, ristoranti raffinati, negozi e club ed è un'area estremamente vivace.",read_more:["\u003Ca href=\"\u002Fit\u002Fhollywood\u002F\"\u003E» Per maggiori informazioni\u003C\u002Fa\u003E"]}]},testimonials:{title:"Testimonianze degli studenti",seemoreBtn:"Vedi di più",TestimonialLink:"\u002Fit\u002Ftestimonials",readmoreBtn:"Leggi di più"},dir:"\u002Fhome",path:"\u002Fhome\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:29.594Z",updatedAt:"2025-05-26T12:06:27.783Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Fit\u002Ffeature\u002F\"\u003E» Per maggiori informazioni\u003C\u002Fa\u003E","it","Mentor Language Institute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));